WITH matched_keys AS (SELECT id FROM shipments EXCEPT DISTINCT SELECT id FROM shipments WHERE delivered_date BETWEEN '2023-03-03' AND '2025-05-23'), reconciled AS (SELECT s.* FROM shipments s JOIN matched_keys k ON s.id = k.id), scored AS (SELECT *, ROUND(cost / SUM(cost) OVER (PARTITION BY YEAR(delivered_date), order_id), 4) AS cost_share, ROUND(cost / SUM(cost) OVER (PARTITION BY order_id, status), 4) AS cost_share_2, SUM(cost) OVER (PARTITION BY status, carrier) AS status_sum_cost FROM reconciled), valid AS (SELECT id, order_id, carrier, cost, status, cost_share_2, status_sum_cost, cost / NULLIF(cost_share, 0) AS cost_per_cost_share, TRIM(status) AS clean_status, COALESCE(carrier, 'OTHER') AS resolved_carrier FROM scored WHERE delivered_date > TO_DATE('2023-04-16')), with_windows AS (SELECT id, cost, cost_share_2, clean_status, resolved_carrier, MAX(cost_per_cost_share) OVER w_recent AS order_id_max_cost_per_cost_share, RANK() OVER w_ordered AS status_sum_cost_rank, AVG(cost_per_cost_share) OVER (PARTITION BY carrier) AS carrier_avg_cost_per_cost_share, COUNT(cost_per_cost_share) OVER w_hist AS status_count_cost_per_cost_share, ROUND(status_sum_cost / SUM(status_sum_cost) OVER (PARTITION BY carrier), 4) AS status_sum_cost_share FROM valid WINDOW w_recent AS (PARTITION BY order_id), w_ordered AS (PARTITION BY status ORDER BY status_sum_cost DESC), w_hist AS (PARTITION BY status, carrier)), scored_shipments AS (SELECT id, clean_status, resolved_carrier, order_id_max_cost_per_cost_share, carrier_avg_cost_per_cost_share, DENSE_RANK() OVER (ORDER BY carrier_avg_cost_per_cost_share DESC NULLS LAST) AS carrier_avg_cost_per_cost_share_dense_rank, DENSE_RANK() OVER (ORDER BY status_sum_cost_share DESC) AS status_sum_cost_share_dense_rank, DENSE_RANK() OVER (ORDER BY order_id_max_cost_per_cost_share NULLS LAST) AS order_id_max_cost_per_cost_share_dense_rank FROM with_windows) SELECT CASE WHEN carrier_avg_cost_per_cost_share_dense_rank >= 8 THEN 'HIGH' ELSE 'LOW' END AS carrier_avg_cost_per_cost_share_dense_rank_tier, CASE WHEN order_id_max_cost_per_cost_share_dense_rank >= 9 THEN 'LARGE' ELSE 'SMALL' END AS order_id_max_cost_per_cost_share_dense_rank_tier, COUNT(*) AS num_rows, ROUND(AVG(status_sum_cost_share_dense_rank), 2) AS avg_status_sum_cost_share_dense_rank FROM scored_shipments GROUP BY GROUPING SETS ((CASE WHEN carrier_avg_cost_per_cost_share_dense_rank >= 8 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN order_id_max_cost_per_cost_share_dense_rank >= 9 THEN 'LARGE' ELSE 'SMALL' END), (CASE WHEN carrier_avg_cost_per_cost_share_dense_rank >= 8 THEN 'HIGH' ELSE 'LOW' END));
